package com.routeflow.app.core.util

import java.util.Locale
import kotlin.math.roundToInt

object OsrmRoutingHelper {

    /**
     * Decodes an OSRM Polyline6 encoded string into a list of (latitude, longitude) coordinate pairs.
     * Uses 1e6 precision as generated by OSRM `geometries=polyline6`.
     */
    fun decodePolyline6(encoded: String): List<Pair<Double, Double>> {
        val poly = ArrayList<Pair<Double, Double>>()
        var index = 0
        val len = encoded.length
        var lat = 0
        var lng = 0

        while (index < len) {
            var b: Int
            var shift = 0
            var result = 0
            do {
                b = encoded[index++].code - 63
                result = result or ((b and 0x1f) shl shift)
                shift += 5
            } while (b >= 0x20)
            val dlat = if ((result and 1) != 0) (result shr 1).inv() else (result shr 1)
            lat += dlat

            shift = 0
            result = 0
            do {
                b = encoded[index++].code - 63
                result = result or ((b and 0x1f) shl shift)
                shift += 5
            } while (b >= 0x20)
            val dlng = if ((result and 1) != 0) (result shr 1).inv() else (result shr 1)
            lng += dlng

            val pLat = lat.toDouble() / 1e6
            val pLng = lng.toDouble() / 1e6
            poly.add(Pair(pLat, pLng))
        }
        return poly
    }

    /**
     * Human-friendly road distance formatting (e.g. "4.2 km" or "750 m")
     */
    fun formatDistance(meters: Double): String {
        return if (meters < 1000.0) {
            "${meters.roundToInt()} m"
        } else {
            String.format(Locale.US, "%.1f km", meters / 1000.0)
        }
    }

    /**
     * Human-friendly driving duration formatting (e.g. "18 mins" or "1 hr 12 mins")
     */
    fun formatDuration(seconds: Double): String {
        val totalSecs = seconds.roundToInt()
        return when {
            totalSecs < 60 -> "${totalSecs} sec"
            totalSecs < 3600 -> "${(totalSecs / 60)} mins"
            else -> {
                val hours = totalSecs / 3600
                val mins = (totalSecs % 3600) / 60
                if (mins > 0) "${hours} hr ${mins} mins" else "${hours} hr"
            }
        }
    }
}
